11	package net.gsantner.markor.util;
12	
13	import android.content.Context;
14	import android.content.Intent;
15	import android.os.Bundle;
16	import android.support.annotation.Nullable;
17	import android.text.InputFilter;
18	import android.text.Spanned;
19	import android.text.TextUtils;
20	
21	import net.gsantner.markor.R;
22	import net.gsantner.markor.format.TextFormat;
23	import net.gsantner.markor.format.markdown.MarkdownTextConverter;
24	import net.gsantner.markor.model.Document;
25	import net.gsantner.opoc.format.todotxt.SttCommander;
26	import net.gsantner.opoc.util.FileUtils;
27	
28	import java.io.File;
29	import java.util.Locale;
30	import java.util.UUID;
31	
32	public class DocumentIO {
33	    public static final String EXTRA_DOCUMENT = "EXTRA_DOCUMENT"; // Document
34	    public static final String EXTRA_PATH = "EXTRA_PATH"; // java.io.File
35	    public static final String EXTRA_PATH_IS_FOLDER = "EXTRA_PATH_IS_FOLDER"; // boolean
36	    public static final String EXTRA_ALLOW_RENAME = "EXTRA_ALLOW_RENAME";
37	
38	    public static final int MAX_TITLE_EXTRACTION_LENGTH = 25;
39	
40	
41	    public static Document loadDocument(Context context, Intent arguments, @Nullable Document existingDocument) {
42	        if (existingDocument != null) {
43	            return existingDocument;
44	        }
45	
46	        Bundle bundle = new Bundle();
47	        if (arguments.hasExtra(EXTRA_DOCUMENT)) {
48	            bundle.putSerializable(EXTRA_DOCUMENT, arguments.getSerializableExtra(EXTRA_DOCUMENT));
49	        } else {
50	            bundle.putBoolean(EXTRA_ALLOW_RENAME, arguments.getBooleanExtra(EXTRA_ALLOW_RENAME, true));
51	            bundle.putSerializable(EXTRA_PATH, arguments.getSerializableExtra(EXTRA_PATH));
52	            bundle.putBoolean(EXTRA_PATH_IS_FOLDER, arguments.getBooleanExtra(EXTRA_PATH_IS_FOLDER, false));
53	        }
54	        return loadDocument(context, bundle, existingDocument);
55	    }
56	
57	    @SuppressWarnings({"ConstantConditions", "ResultOfMethodCallIgnored"})
58	    public static synchronized Document loadDocument(Context context, Bundle arguments, @Nullable Document existingDocument) {
59	        if (existingDocument != null) {
60	            return existingDocument;
61	        }
62	
63	        // When called directly from a filepath
64	        if (arguments.containsKey(EXTRA_DOCUMENT)) {
65	            return (Document) arguments.getSerializable(EXTRA_DOCUMENT);
66	        }
67	
68	        Document document = new Document();
69	        document.setDoHistory(false);
70	        document.setFileExtension(MarkdownTextConverter.EXT_MARKDOWN__MD);
71	        File extraPath = (File) arguments.getSerializable(EXTRA_PATH);
72	        File filePath = extraPath;
73	
74	        // Generate random not existing filepath if filename not specified
75	        boolean extraPathIsFolder = arguments.getBoolean(EXTRA_PATH_IS_FOLDER);
76	        if (extraPathIsFolder) {
77	            extraPath.mkdirs();
78	            while (filePath.exists()) {
79	                filePath = new File(extraPath, String.format("%s-%s.%s", context.getString(R.string.document), UUID.randomUUID().toString(), MarkdownTextConverter.EXT_MARKDOWN__MD));
80	            }
81	        } else if (filePath.isFile() && filePath.canRead()) {
82	            // Extract existing extension
83	            for (String ext : MarkdownTextConverter.MD_EXTENSIONS) {
84	                if (filePath.getName().toLowerCase(Locale.getDefault()).endsWith(ext)) {
85	                    document.setFileExtension(ext);
86	                    break;
87	                }
88	            }
89	
90	            // Extract content and title
91	            document.setTitle(MarkdownTextConverter.MD_EXTENSION_PATTERN.matcher(filePath.getName()).replaceAll(""));
92	            document.setContent(FileUtils.readTextFileFast(filePath));
93	        }
94	
95	        document.setFile(filePath);
96	
97	        if (document.getFormat() == TextFormat.FORMAT_UNKNOWN) {
98	            String fnlower = document.getFile().getName().toLowerCase();
99	
100	            if (SttCommander.TODOTXT_FILE_PATTERN.matcher(fnlower).matches()) {
101	                document.setFormat(TextFormat.FORMAT_TODOTXT);
102	            } else if (MarkdownTextConverter.isMarkdownFile(filePath)) {
103	                document.setFormat(TextFormat.FORMAT_MARKDOWN);
104	            } else if (fnlower.endsWith(".txt")) {
105	                document.setFormat(TextFormat.FORMAT_PLAIN);
106	            } else {
107	                document.setFormat(TextFormat.FORMAT_PLAIN);
108	            }
109	        }
110	
111	        document.setDoHistory(true);
112	        return document;
113	    }
114	
115	    public static synchronized boolean saveDocument(Document document, boolean argAllowRename, String currentText) {
116	        boolean ret;
117	        String filename = DocumentIO.normalizeTitleForFilename(document) + document.getFileExtension();
118	        document.setDoHistory(true);
119	        document.setFile(new File(document.getFile().getParentFile(), filename));
120	
121	        Document documentInitial = document.getInitialVersion();
122	        if (argAllowRename) {
123	            if (!document.getFile().equals(documentInitial.getFile())) {
124	                if (documentInitial.getFile().exists()) {
125	                    if (FileUtils.renameFile(documentInitial.getFile(), document.getFile())) {
126	                        // Rename succeeded -> Rename everything in history too
127	                        for (Document hist : document.getHistory()) {
128	                            hist.setFile(document.getFile());
129	                            for (Document hist2 : hist.getHistory()) {
130	                                hist2.setFile(document.getFile());
131	                            }
132	                        }
133	                    }
134	                }
135	            }
136	        } else {
137	            document.setFile(documentInitial.getFile());
138	        }
139	
140	        if (!currentText.equals(documentInitial.getContent())) {
141	            document.forceAddNextChangeToHistory();
142	            document.setContent(currentText);
143	            ret = FileUtils.writeFile(document.getFile(), document.getContent());
144	        } else {
145	            ret = true;
146	        }
147	        return ret;
148	    }
149	
150	    public static String normalizeTitleForFilename(Document _document) {
151	        String name = _document.getTitle();
152	        try {
153	            if (name.length() == 0) {
154	                if (_document.getContent().length() == 0) {
155	                    return null;
156	                } else {
157	                    String contentL1 = _document.getContent().split("\n")[0];
158	                    if (contentL1.length() < MAX_TITLE_EXTRACTION_LENGTH) {
159	                        name = contentL1.substring(0, contentL1.length());
160	                    } else {
161	                        name = contentL1.substring(0, MAX_TITLE_EXTRACTION_LENGTH);
162	                    }
163	                }
164	            }
165	            name = name.replaceAll("[\\\\/:\"´`'*$?<>\n\r@|#]+", "").trim();
166	        } catch (Exception ignored) {
167	        }
168	        if (name == null || name.isEmpty()) {
169	            name = "Note " + UUID.randomUUID().toString();
170	        }
171	        return name;
172	    }
173	
174	    public static final InputFilter INPUT_FILTER_FILESYSTEM_FILENAME = new InputFilter() {
175	        private final String blockCharacterSet = "\\/:\"´`'*?<>\n\r@|";
176	
177	        public CharSequence filter(CharSequence source, int start, int end, Spanned dest, int dstart, int dend) {
178	            for (int i = 0; !TextUtils.isEmpty(source) && i < source.length(); i++) {
179	                if (blockCharacterSet.contains(("" + source.charAt(i)))) {
180	                    return "";
181	                }
182	            }
183	            return null;
184	        }
185	    };
186	}
