96	    @Override
97	    public void onViewCreated(@NonNull View view, Bundle savedInstanceState) {
98	        super.onViewCreated(view, savedInstanceState);
99	        //applyTextFormat(TextFormat.FORMAT_PLAIN);
100	        setupAppearancePreferences(view);
101	
102	        if (savedInstanceState != null && savedInstanceState.containsKey(SAVESTATE_DOCUMENT)) {
103	            _document = (Document) savedInstanceState.getSerializable(SAVESTATE_DOCUMENT);
104	        }
105	        _document = loadDocument();
106	        loadDocumentIntoUi();
107	        if (savedInstanceState != null && savedInstanceState.containsKey(SAVESTATE_CURSOR_POS)) {
108	            int cursor = savedInstanceState.getInt(SAVESTATE_CURSOR_POS);
109	            if (cursor >= 0 && cursor < _hlEditor.length()) {
110	                _hlEditor.setSelection(cursor);
111	            }
112	        }
113	
114	        new ActivityUtils(getActivity()).hideSoftKeyboard();
115	        AppSettings appSettings = new AppSettings(view.getContext());
116	        _hlEditor.clearFocus();
117	        _hlEditor.setLineSpacing(0, appSettings.getEditorLineSpacing());
118	    }
