141	    @Override
142	    public void onCreateOptionsMenu(Menu menu, MenuInflater inflater) {
143	        super.onCreateOptionsMenu(menu, inflater);
144	        inflater.inflate(R.menu.document__edit__menu, menu);
145	        ContextUtils cu = ContextUtils.get();
146	        cu.tintMenuItems(menu, true, Color.WHITE);
147	        cu.setSubMenuIconsVisiblity(menu, true);
148	
149	        AppSettings appSettings = new AppSettings(getActivity());
150	        menu.findItem(R.id.action_undo).setVisible(appSettings.isEditorHistoryEnabled());
151	        menu.findItem(R.id.action_redo).setVisible(appSettings.isEditorHistoryEnabled());
152	
153	        boolean enable;
154	        Drawable drawable;
155	        drawable = menu.findItem(R.id.action_undo).setEnabled(_document.canGoToEarlierVersion()).getIcon();
156	        drawable.mutate().setAlpha(_document.canGoToEarlierVersion() ? 255 : 40);
157	        drawable = menu.findItem(R.id.action_redo).setEnabled(_document.canGoToNewerVersion()).getIcon();
158	        drawable.mutate().setAlpha(_document.canGoToNewerVersion() ? 255 : 40);
159	        enable = !(_document.getContent().isEmpty() || _document.getTitle().isEmpty());
160	        drawable = menu.findItem(R.id.action_save).setEnabled(enable).getIcon();
161	        drawable.mutate().setAlpha(enable ? 255 : 40);
162	    }
163	
164	    public void loadDocumentIntoUi() {
165	        int editorpos = _hlEditor.getSelectionStart();
166	        _hlEditor.setText(_document.getContent());
167	        editorpos = editorpos > _hlEditor.length() ? _hlEditor.length() - 1 : editorpos;
168	        _hlEditor.setSelection(editorpos < 0 ? 0 : editorpos);
169	        Activity activity = getActivity();
170	        if (activity != null && activity instanceof DocumentActivity) {
171	            DocumentActivity da = ((DocumentActivity) activity);
172	            da.setDocumentTitle(_document.getTitle());
173	            da.setDocument(_document);
174	        }
175	        applyTextFormat(_document.getFormat());
176	        _textFormat.getTextModuleActions().setDocument(_document);
177	    }
178	
179	    @Override
180	    public boolean onOptionsItemSelected(MenuItem item) {
181	        switch (item.getItemId()) {
182	            case R.id.action_undo: {
183	                if (_document.canGoToEarlierVersion()) {
184	                    _document.goToEarlierVersion();
185	                    loadDocumentIntoUi();
186	                }
187	                return true;
188	            }
189	            case R.id.action_redo: {
190	                if (_document.canGoToNewerVersion()) {
191	                    _document.goToNewerVersion();
192	                    loadDocumentIntoUi();
193	                }
194	                return true;
195	            }
196	            case R.id.action_save: {
197	                saveDocument();
198	                return true;
199	            }
200	        }
201	        return super.onOptionsItemSelected(item);
202	    }
