240	    public void applyTextFormat(int textFormatId) {
241	        _textModuleActionsBar.removeAllViews();
242	        _textFormat = TextFormat.getFormat(textFormatId, getActivity(), _document);
243	        _hlEditor.setHighlighter(_textFormat.getHighlighter());
244	        _textFormat.getTextModuleActions()
245	                .setHighlightingEditor(_hlEditor)
246	                .appendTextModuleActionsToBar(_textModuleActionsBar);
247	        if (_textModuleActionsBar.getChildCount() == 0) {
248	            _textModuleActionsBar.setVisibility(View.GONE);
249	        } else {
250	            _textModuleActionsBar.setVisibility(View.VISIBLE);
251	        }
252	    }
