254	    private void setupAppearancePreferences(View fragmentView) {
255	        AppSettings as = AppSettings.get();
256	        _hlEditor.setTextSize(TypedValue.COMPLEX_UNIT_SP, as.getFontSize());
257	        _hlEditor.setTypeface(Typeface.create(as.getFontFamily(), Typeface.NORMAL));
258	
259	        if (as.isDarkThemeEnabled()) {
260	            _hlEditor.setBackgroundColor(getResources().getColor(R.color.dark_grey));
261	            _hlEditor.setTextColor(getResources().getColor(android.R.color.white));
262	            fragmentView.findViewById(R.id.document__fragment__edit__textmodule_actions_bar__scrolling_parent).setBackgroundColor(getResources().getColor(R.color.dark_grey));
263	        } else {
264	            _hlEditor.setBackgroundColor(getResources().getColor(R.color.light__background));
265	            _hlEditor.setTextColor(getResources().getColor(R.color.dark_grey));
266	            fragmentView.findViewById(R.id.document__fragment__edit__textmodule_actions_bar__scrolling_parent)
267	                    .setBackgroundColor(getResources().getColor(R.color.lighter_grey));
268	        }
269	    }
