271	    @Override
272	    public String getFragmentTag() {
273	        return FRAGMENT_TAG;
274	    }
275	
276	    @Override
277	    public boolean onBackPressed() {
278	        saveDocument();
279	        if (showPreviewOnBack) {
280	            showPreviewOnBack = false;
281	            Activity activity = getActivity();
282	            if (activity != null && activity instanceof DocumentActivity) {
283	                DocumentActivity da = ((DocumentActivity) activity);
284	                da.showPreview(_document, null);
285	            }
286	            return true;
287	        }
288	        return false;
289	    }
290	
291	    // Save the file
292	    // Only supports java.io.File. TODO: Android Content
293	    public boolean saveDocument() {
294	        boolean ret = false;
295	        if (isAdded() && _hlEditor != null) {
296	            boolean argAllowRename = getArguments() == null || getArguments().getBoolean(DocumentIO.EXTRA_ALLOW_RENAME, true);
297	            ret = DocumentIO.saveDocument(_document, argAllowRename, _hlEditor.getText().toString());
298	            updateLauncherWidgets();
299	        }
300	        return ret;
301	    }
302	
303	    @Override
304	    public void onSaveInstanceState(@NonNull Bundle outState) {
305	        saveDocument();
306	        if ((_hlEditor.length() * _document.getHistory().size() * 1.05) < 9200) {
307	            outState.putSerializable(SAVESTATE_DOCUMENT, _document);
308	        }
309	        if (getArguments() != null && _document.getFile() != null) {
310	            getArguments().putSerializable(DocumentIO.EXTRA_PATH, _document.getFile());
311	            getArguments().putSerializable(DocumentIO.EXTRA_PATH_IS_FOLDER, false);
312	        }
313	        if (_hlEditor != null) {
314	            outState.putSerializable(SAVESTATE_CURSOR_POS, _hlEditor.getSelectionStart());
315	        }
316	        super.onSaveInstanceState(outState);
317	    }
318	
319	    @Override
320	    public void onPause() {
321	        super.onPause();
322	        saveDocument();
323	        if (_document != null && _document.getFile() != null) {
324	            AppSettings appSettings = new AppSettings(getContext());
325	            appSettings.addRecentDocument(_document.getFile());
326	        }
327	    }
