59	    public synchronized boolean canGoToEarlierVersion() {
60	        // Position 5, History is 5 big, yes
61	        // Position 3, History is 5 big, yes
62	        // Position 0, History is 5 big, no
63	        // Position 0, History is 0 big, no
64	        return _historyPosition > 0 && _history.size() > 0;
65	    }
66	
67	    public synchronized boolean canGoToNewerVersion() {
68	        // Position 5, History is 5 big, no
69	        // Position 3, History is 5 big, yes
70	        // Position 0, History is 5 big, yes
71	        // Position 0, History is 0 big, no
72	        return _historyPosition < _history.size() - 1;
73	    }
74	
75	    public synchronized void goToEarlierVersion() {
76	        if (canGoToEarlierVersion()) {
77	            // If we are at the current state, but this was not saved yet -> save current state
78	            if (hasChangesNotInHistory()) {
79	                forceAddNextChangeToHistory();
80	                addToHistory();
81	                _historyPosition--;
82	            }
83	
84	            _historyPosition--;
85	            if (_historyPosition >= 0 && _historyPosition < _history.size()) {
86	                loadFromDocument(_history.get(_historyPosition));
87	            }
88	        }
89	    }
90	
91	    public boolean hasChangesNotInHistory() {
92	        return _historyPosition == _history.size() && (_history.size() == 0 || !_history.get(_history.size() - 1).equals(this));
93	    }
94	
95	    public synchronized void goToNewerVersion() {
96	        if (canGoToNewerVersion()) {
97	            _historyPosition++;
98	            loadFromDocument(_history.get(_historyPosition));
99	        }
100	    }
101	
102	    public synchronized void addToHistory() {
103	        if (_doHistory && (((_lastChanged + MIN_HISTORY_DELAY) < System.currentTimeMillis()))) {
104	            while (_historyPosition != _history.size() && _history.size() != 0) {
105	                _history.remove(_history.size() - 1);
106	            }
107	            if (_history.size() >= MAX_HISTORY_SIZE) {
108	                _history.remove(2);
109	                _historyPosition--;
110	            }
111	            if (_history.isEmpty() || (!_history.isEmpty() && !_history.get(_history.size() - 1).equals(this))) {
112	                _history.add(cloneDocument());
113	                _historyPosition++;
114	                _lastChanged = System.currentTimeMillis();
115	            }
116	        }
117	    }
