152	    public synchronized Document getInitialVersion() {
153	        if (hasChangesNotInHistory()) {
154	            boolean history = _doHistory;
155	            setDoHistory(true);
156	            addToHistory();
157	            setDoHistory(history);
158	        }
159	        return _history.size() == 0 ? this : _history.get(0);
160	    }
