        if (argAllowRename) {
            if (!document.getFile().equals(init.getFile()) && init.getFile().exists()) {
                init.getFile().renameTo(document.getFile());
            }
        } else {
            document.setFile(init.getFile());
        }
        if (!currentText.equals(init.getContent())) {
            document.forceAddNextChangeToHistory();
            document.setContent(currentText);
            ret = writeFile(document.getFile(), document.getContent());
        } else {
            ret = true;
        }
        return ret;
    }

    // ---- NEW (patched) save ----
    static boolean saveNew(Document document, boolean argAllowRename, String currentText) {
        boolean ret;
        String filename = normalizeTitleForFilename(document) + document.getFileExtension();
        document.setDoHistory(true);
        document.setFile(new File(document.getFile().getParentFile(), filename));
        Document init = document.getInitialVersion();
        if (argAllowRename) {
            if (!document.getFile().equals(init.getFile()) && init.getFile().exists()) {
                init.getFile().renameTo(document.getFile());
            }
        } else {
            document.setFile(init.getFile());
        }
        if (!currentText.equals(document.getContent())) {
            document.forceAddNextChangeToHistory();
            document.setContent(currentText);
        }
        final File target = document.getFile();
        if (!target.exists() || !currentText.equals(readTextFileFast(target))) {
            ret = writeFile(target, document.getContent());
        } else {
            ret = true;
        }
        return ret;
    }

    // ---- fragment loadDocument() initial snapshot ----
    static void initialSnapshot(Document d, boolean patched) {
        if (!d.getHistory().isEmpty()) return;
        if (patched) {
            boolean dh = d.isDoHistory();
            d.setDoHistory(true);
            d.forceAddNextChangeToHistory();
            d.addToHistory();
            d.setDoHistory(dh);
        } else {
            d.forceAddNextChangeToHistory();
            d.addToHistory();
        }
    }

    static Document newNoteDoc(boolean historyPref, boolean patched) {
        Document d = new Document();
        d.setDoHistory(false);
        d.setFileExtension(".md");
        d.setFile(new File(DIR, "Document-" + UUID.randomUUID() + ".md"));
        d.setDoHistory(true);
        d.setDoHistory(historyPref); // fragment loadDocument()
        initialSnapshot(d, patched);
        return d;
    }

    static Document existingNoteDoc(File file, boolean historyPref, boolean patched) {
        Document d = new Document();
        d.setDoHistory(false);
        d.setFileExtension(".md");
        d.setTitle(file.getName().replace(".md", ""));
        d.setContent(readTextFileFast(file));
        d.setFile(file);
        d.setDoHistory(true);
        d.setDoHistory(historyPref);
        initialSnapshot(d, patched);
        return d;
    }

    interface Saver { boolean save(Document d, boolean rename, String text); }

    // Repro: new note, type title + content, WAIT (delayed runnable pushes text into
    // the document -> save icon enabled), press save, then back (onPause -> save again)
    static String scenarioWaitThenSave(boolean historyPref, boolean patched, Saver s) throws Exception {
        Document d = newNoteDoc(historyPref, patched);
        d.setTitle("MyNote");                      // toolbar title TextChanged
        Thread.sleep(1600);
        d.setContent("Hello content");             // HISTORY_DELTA runnable after 5s
        s.save(d, true, "Hello content");          // press save icon
        Thread.sleep(100);
        s.save(d, true, "Hello content");          // back -> onPause -> saveDocument()
        File f = new File(DIR, "MyNote.md");
        return f.exists() ? "CREATED (" + readTextFileFast(f) + ")" : "*** NOT CREATED ***";
    }

    // Control: new note, back pressed before the 5s runnable fires
    static String scenarioBackOnly(boolean historyPref, boolean patched, Saver s) throws Exception {
        Document d = newNoteDoc(historyPref, patched);
        d.setTitle("MyNote2");
        s.save(d, true, "Hello content");          // onPause only
        File f = new File(DIR, "MyNote2.md");
        return f.exists() ? "CREATED (" + readTextFileFast(f) + ")" : "*** NOT CREATED ***";
    }

    // Existing note: open, edit, wait, press save, back
    static String scenarioEditExisting(boolean historyPref, boolean patched, Saver s) throws Exception {
        File f = new File(DIR, "Existing.md");
        writeFile(f, "old text");
        Document d = existingNoteDoc(f, historyPref, patched);
        Thread.sleep(1600);
        d.setContent("old text + new");
        s.save(d, true, "old text + new");
        Thread.sleep(100);
        s.save(d, true, "old text + new");
        String disk = readTextFileFast(f);
        return disk.equals("old text + new") ? "SAVED (" + disk + ")" : "*** LOST (disk=" + disk + ") ***";
    }

    // Rename: existing note, change title, save
    static String scenarioRename(boolean historyPref, boolean patched, Saver s) throws Exception {
        File f = new File(DIR, "Before.md");
        writeFile(f, "body");
        Document d = existingNoteDoc(f, historyPref, patched);
        d.setTitle("After");
        s.save(d, true, "body");
        File after = new File(DIR, "After.md");
        return (after.exists() && !f.exists()) ? "RENAMED ok (" + readTextFileFast(after) + ")"
                : "*** rename issue: Before=" + f.exists() + " After=" + after.exists() + " ***";
    }

    static void run(boolean patched, Saver s) throws Exception {
        for (boolean histPref : new boolean[]{false, true}) {
            DIR = Files.createTempDirectory("notes").toFile();
            System.out.println("  [editorHistoryEnabled=" + histPref + "]");
            System.out.println("    wait-then-save (BUG REPRO)  : " + scenarioWaitThenSave(histPref, patched, s));
            System.out.println("    back-only (worked before)   : " + scenarioBackOnly(histPref, patched, s));
            System.out.println("    edit existing note          : " + scenarioEditExisting(histPref, patched, s));
            System.out.println("    rename on save              : " + scenarioRename(histPref, patched, s));
        }
    }

    public static void main(String[] a) throws Exception {
        System.out.println("=== BEFORE PATCH ===");
        run(false, Sim::saveOld);
        System.out.println("=== AFTER PATCH ===");
        run(true, Sim::saveNew);
    }
