115	    public static synchronized boolean saveDocument(Document document, boolean argAllowRename, String currentText) {
116	        boolean ret;
117	        String filename = DocumentIO.normalizeTitleForFilename(document) + document.getFileExtension();
118	        document.setDoHistory(true);
119	        document.setFile(new File(document.getFile().getParentFile(), filename));
120	
121	        Document documentInitial = document.getInitialVersion();
122	        if (argAllowRename) {
123	            if (!document.getFile().equals(documentInitial.getFile())) {
124	                if (documentInitial.getFile().exists()) {
125	                    if (FileUtils.renameFile(documentInitial.getFile(), document.getFile())) {
126	                        // Rename succeeded -> Rename everything in history too
127	                        for (Document hist : document.getHistory()) {
128	                            hist.setFile(document.getFile());
129	                            for (Document hist2 : hist.getHistory()) {
130	                                hist2.setFile(document.getFile());
131	                            }
132	                        }
133	                    }
134	                }
135	            }
136	        } else {
137	            document.setFile(documentInitial.getFile());
138	        }
139	
140	        // Keep the in-memory document in sync with the text of the editor
141	        if (!currentText.equals(document.getContent())) {
142	            document.forceAddNextChangeToHistory();
143	            document.setContent(currentText);
144	        }
145	
146	        // Whether a write is required may only be determined by looking at the file itself.
147	        // The in-memory (history) state is not usable for that decision: when the editor
148	        // history is disabled (default) no initial version exists, so getInitialVersion()
149	        // creates it lazily - already containing the current text. Comparing against it
150	        // made saving skip the write completely, hence new documents were never created
151	        // and changes to existing ones got lost.
152	        final File targetFile = document.getFile();
153	        if (!targetFile.exists() || !currentText.equals(FileUtils.readTextFileFast(targetFile))) {
154	            ret = FileUtils.writeFile(targetFile, document.getContent());
155	        } else {
156	            ret = true;
157	        }
158	        return ret;
159	    }
