132	    }
133	
134	    public synchronized void setTitle(String title) {
135	        if (!equalsc(getTitle(), title)) {
136	            addToHistory();
137	            _title = title;
138	        }
139	    }
140	
141	    public synchronized String getContent() {
142	        return _content;
143	    }
144	
145	    public synchronized void setContent(String content) {
146	        if (!equalsc(getContent(), content)) {
147	            addToHistory();
148	            _content = content;
149	        }
150	    }
151	
152	    public synchronized Document getInitialVersion() {
153	        if (hasChangesNotInHistory()) {
154	            boolean history = _doHistory;
155	            setDoHistory(true);
156	            addToHistory();
157	            setDoHistory(history);
158	        }
159	        return _history.size() == 0 ? this : _history.get(0);
160	    }
161	
162	    @Override
163	    public boolean equals(Object obj) {
164	        if (obj instanceof Document) {
165	            Document other = ((Document) obj);
166	            return equalsc(getFile(), other.getFile())
167	                    && equalsc(getTitle(), other.getTitle())
168	                    && equalsc(getContent(), other.getContent());
169	        }
170	        return super.equals(obj);
171	    }
172	
173	    private static boolean equalsc(Object o1, Object o2) {
174	        return (o1 == null && o2 == null) || o1 != null && o1.equals(o2);
175	    }
